 static readonly JsonSerializerOptions json=new(JsonSerializerDefaults.Web); static readonly System.Collections.Concurrent.ConcurrentDictionary<string,(string UserId,DateTime Expires)> sessions=new(); static readonly System.Collections.Concurrent.ConcurrentDictionary<string,(string TransferToken,DateTime Expires)> transferSessions=new();
 public static async Task Run(StateStore store){var l=new HttpListener();l.Prefixes.Add(store.State.Settings.ListenPrefix);l.Start();while(true){var c=await l.GetContextAsync();_=Task.Run(()=>Handle(c,store));}}
 static async Task Handle(HttpListenerContext c,StateStore store){try{CleanupTransfers(store);var p=c.Request.Url?.AbsolutePath??"/";if(p=="/brand-logo"){var b=Convert.FromBase64String(BrandLogo.DataUri.Split(',')[1]);c.Response.ContentType="image/jpeg";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();return;}if((p=="/"||p=="/index.html")&&c.Request.HttpMethod=="GET"){var web=Path.Combine(AppContext.BaseDirectory,"web","index.html");if(!File.Exists(web)){await Reply(c,404,new{error="Webclient nicht gefunden"});return;}var b=await File.ReadAllBytesAsync(web);c.Response.StatusCode=200;c.Response.ContentType="text/html; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();return;}if(p.StartsWith("/transfer/")){var parts=p.Split('/',StringSplitOptions.RemoveEmptyEntries);var token=parts.Length>1?parts[1]:"";var t=store.State.Transfers.FirstOrDefault(x=>x.Token==token);if(t==null||t.ExpiresUtc!=null&&t.ExpiresUtc<=DateTime.UtcNow){await Html(c,404,"<h2>Transferlink ungültig oder abgelaufen</h2>");return;}var s=store.State.Storage.FirstOrDefault(x=>x.Id==t.StorageId);if(s==null){await Html(c,404,"<h2>Transfer nicht gefunden</h2>");return;}var transferAuth=c.Request.Cookies["transfer_auth"]?.Value??"";var unlocked=string.IsNullOrEmpty(t.PasswordHash)||(transferSessions.TryGetValue(transferAuth,out var ts)&&ts.TransferToken==token&&ts.Expires>DateTime.UtcNow);if(!unlocked&&c.Request.HttpMethod=="POST"&&parts.Length>2&&parts[2]=="unlock"){using var sr=new StreamReader(c.Request.InputStream,c.Request.ContentEncoding);var form=await sr.ReadToEndAsync();var password=Uri.UnescapeDataString(form.StartsWith("password=")?form[9..].Replace("+"," "):"");if(StateStore.Verify(password,t.PasswordHash)){var key=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(24));transferSessions[key]=(token,DateTime.UtcNow.AddHours(2));c.Response.SetCookie(new Cookie("transfer_auth",key,"/transfer/"+token){HttpOnly=true,Secure=c.Request.IsSecureConnection});c.Response.Redirect("/transfer/"+token);c.Response.Close();return;}await Html(c,200,TransferPage(t,token,true));return;}if(!unlocked){await Html(c,200,TransferPage(t,token,false));return;}if(parts.Length>2&&parts[2]=="download"){if(!t.AllowDownload){await Reply(c,403,new{error="Download nicht erlaubt"});return;}var file=SafePath(s.Path,t.RelativePath);if(file==null||!File.Exists(file)){await Reply(c,404,new{error="Datei nicht gefunden"});return;}c.Response.StatusCode=200;c.Response.ContentType="application/octet-stream";c.Response.AddHeader("Content-Disposition","attachment; filename=\""+Path.GetFileName(file).Replace("\"","")+"\"");c.Response.ContentLength64=new FileInfo(file).Length;await using(var fs=File.OpenRead(file))await fs.CopyToAsync(c.Response.OutputStream);c.Response.Close();return;}if(parts.Length>2&&parts[2]=="upload"&&c.Request.HttpMethod=="POST"){if(!t.AllowUpload){await Reply(c,403,new{error="Upload nicht erlaubt"});return;}var basePath=SafePath(s.Path,t.RelativePath);var dir=basePath!=null&&Directory.Exists(basePath)?basePath:basePath==null?null:Path.GetDirectoryName(basePath);var name=Path.GetFileName(c.Request.QueryString["name"]??"");if(dir==null||string.IsNullOrWhiteSpace(name)){await Reply(c,400,new{error="Ungültiger Upload"});return;}await using(var fs=File.Create(Path.Combine(dir,name)))await c.Request.InputStream.CopyToAsync(fs);await Reply(c,201,new{ok=true});return;}await Html(c,200,TransferPage(t,token,false));return;}if(p=="/api/health"){await Reply(c,200,new{status="ok",product="i-NET-PROMO Cloudservice"});return;}if(p=="/api/login"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<Login>(c.Request.InputStream,json);var u=store.State.Users.FirstOrDefault(x=>x.UserName.Equals(q?.UserName,StringComparison.OrdinalIgnoreCase));if(u==null||!StateStore.Verify(q?.Password??"",u.PasswordHash)){await Reply(c,401,new{error="Anmeldung fehlgeschlagen"});return;}var token=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(32));sessions[token]=(u.Id,DateTime.UtcNow.AddHours(12));await Reply(c,200,new{token,u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes});return;}if(p=="/api/logout"&&c.Request.HttpMethod=="POST"){var h=c.Request.Headers["Authorization"];if(h!=null&&h.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase))sessions.TryRemove(h[7..].Trim(),out _);await Reply(c,200,new{ok=true});return;}var auth=Authenticate(c,store);if(auth==null){await Reply(c,401,new{error="Nicht angemeldet"});return;}var current=auth;if(p=="/api/transfers"&&c.Request.HttpMethod=="GET"){await Reply(c,200,store.State.Transfers.Where(t=>current.IsAdmin||t.OwnerUserId==current.Id).Select(t=>new{t.Id,t.Token,t.StorageId,t.RelativePath,t.ExpiresUtc,t.AllowDownload,t.AllowUpload,t.AutoDeleteDays,t.CreatedUtc,HasPassword=!string.IsNullOrEmpty(t.PasswordHash)}));return;}if(p=="/api/transfers"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<TransferRequest>(c.Request.InputStream,json);if(q==null){await Reply(c,400,new{error="Ungültiger Transfer"});return;}var s=store.State.Storage.FirstOrDefault(x=>x.Id==q.StorageId);if(s==null||!CanAccess(s,current)){await Reply(c,400,new{error="Ungültiger Transfer"});return;}var t=new TransferLink{OwnerUserId=current.Id,StorageId=q.StorageId,RelativePath=q.RelativePath??"",PasswordHash=string.IsNullOrWhiteSpace(q.Password)?"":StateStore.Hash(q.Password),ExpiresUtc=q.ExpiresUtc,AllowDownload=q.AllowDownload,AllowUpload=q.AllowUpload,AutoDeleteDays=q.AutoDeleteDays};store.State.Transfers.Add(t);store.Save();await Reply(c,201,new{t.Id,t.Token,t.ExpiresUtc,t.AllowDownload,t.AllowUpload,t.AutoDeleteDays});return;}if(p=="/api/share-users"){await Reply(c,200,store.State.Users.Where(u=>u.Id!=current.Id).Select(u=>new{u.Id,u.UserName,u.DisplayName}));return;}if(p=="/api/users"){if(!current.IsAdmin){await Reply(c,403,new{error="Nicht erlaubt"});return;}await Reply(c,200,store.State.Users.Select(u=>new{u.Id,u.UserName,u.DisplayName,u.IsAdmin,u.QuotaBytes}));return;}if(p=="/api/storage"){await Reply(c,200,current.IsAdmin?store.State.Storage:store.State.Storage.Where(s=>s.UserId==current.Id||s.GroupId!=null&&current.GroupIds.Contains(s.GroupId)).ToList());return;}if(p=="/api/files"&&c.Request.HttpMethod=="GET"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,sid,rel,false)==null)){await Reply(c,403,new{error="Kein Zugriff"});return;}var dir=SafePath(s.Path,rel);if(dir==null||!Directory.Exists(dir)){await Reply(c,404,new{error="Ordner nicht gefunden"});return;}var items=Directory.EnumerateFileSystemEntries(dir).Select(x=>{var isDir=Directory.Exists(x);var fi=isDir?null:new FileInfo(x);return new{Name=Path.GetFileName(x),IsDirectory=isDir,Size=fi?.Length??0,ModifiedUtc=isDir?Directory.GetLastWriteTimeUtc(x):fi!.LastWriteTimeUtc};});await Reply(c,200,items);return;}if(p=="/api/folders"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<FolderRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);var folderRel=Path.Combine(q?.Path??"",q?.Name??"");if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,s.Id,folderRel,true)==null)){await Reply(c,403,new{error="Kein Schreibzugriff"});return;}var dir=SafePath(s.Path,folderRel);if(dir==null){await Reply(c,400,new{error="Ungültiger Pfad"});return;}Directory.CreateDirectory(dir);await Reply(c,201,new{ok=true});return;}if(p=="/api/upload"&&c.Request.HttpMethod=="POST"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var name=Path.GetFileName(c.Request.QueryString["name"]??"");var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);var uploadRel=Path.Combine(rel,name);if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,sid,uploadRel,true)==null)){await Reply(c,403,new{error="Kein Schreibzugriff"});return;}var file=SafePath(s.Path,uploadRel);if(file==null||string.IsNullOrWhiteSpace(name)){await Reply(c,400,new{error="Ungültiger Upload"});return;}var limit=s!.QuotaBytes>0?s.QuotaBytes:current.QuotaBytes;if(limit>0){long used=Directory.Exists(s.Path)?Directory.EnumerateFiles(s.Path,"*",SearchOption.AllDirectories).Sum(x=>new FileInfo(x).Length):0;var incoming=c.Request.ContentLength64>0?c.Request.ContentLength64:0;if(used+incoming>limit){await Reply(c,413,new{error="Speicherlimit überschritten"});return;}}Directory.CreateDirectory(Path.GetDirectoryName(file)!);await using(var fs=File.Create(file))await c.Request.InputStream.CopyToAsync(fs);await Reply(c,201,new{ok=true});return;}if(p=="/api/download"&&c.Request.HttpMethod=="GET"){var sid=c.Request.QueryString["storageId"]??"";var rel=c.Request.QueryString["path"]??"";var s=store.State.Storage.FirstOrDefault(x=>x.Id==sid);if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,sid,rel,false)==null)){await Reply(c,403,new{error="Kein Zugriff"});return;}var file=SafePath(s.Path,rel);if(file==null||!File.Exists(file)){await Reply(c,404,new{error="Datei nicht gefunden"});return;}c.Response.StatusCode=200;c.Response.ContentType="application/octet-stream";c.Response.ContentLength64=new FileInfo(file).Length;await using(var fs=File.OpenRead(file))await fs.CopyToAsync(c.Response.OutputStream);c.Response.Close();return;}
if(p=="/api/delete"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<PathRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,s.Id,q?.Path??"",true)==null)){await Reply(c,403,new{error="Kein Schreibzugriff"});return;}var target=SafePath(s.Path,q?.Path??"");if(target==null){await Reply(c,400,new{error="Ungültiger Pfad"});return;}if(File.Exists(target))File.Delete(target);else if(Directory.Exists(target))Directory.Delete(target,true);else{await Reply(c,404,new{error="Nicht gefunden"});return;}await Reply(c,200,new{ok=true});return;}if(p=="/api/rename"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<RenameRequest>(c.Request.InputStream,json);var s=store.State.Storage.FirstOrDefault(x=>x.Id==q?.StorageId);if(s==null||(!CanAccess(s,current)&&SharedAccess(store,current,s.Id,q?.Path??"",true)==null)){await Reply(c,403,new{error="Kein Schreibzugriff"});return;}var src=SafePath(s.Path,q?.Path??"");var parent=src==null?null:Path.GetDirectoryName(src);var dst=s==null||parent==null?null:SafePath(s.Path,Path.GetRelativePath(s.Path,Path.Combine(parent,Path.GetFileName(q?.NewName??""))));if(src==null||dst==null||string.IsNullOrWhiteSpace(q?.NewName)){await Reply(c,400,new{error="Ungültiger Pfad"});return;}if(File.Exists(src))File.Move(src,dst);else if(Directory.Exists(src))Directory.Move(src,dst);else{await Reply(c,404,new{error="Nicht gefunden"});return;}await Reply(c,200,new{ok=true});return;}if(p=="/api/shares/received"&&c.Request.HttpMethod=="GET"){await Reply(c,200,store.State.Shares.Where(s=>s.TargetUserId==current.Id).Select(s=>new{s.Id,s.OwnerUserId,s.StorageId,s.RelativePath,s.CanWrite,s.CreatedUtc,Owner=store.State.Users.FirstOrDefault(u=>u.Id==s.OwnerUserId)!.UserName}));return;}if(p=="/api/shares"&&c.Request.HttpMethod=="GET"){await Reply(c,200,store.State.Shares.Where(s=>current.IsAdmin||s.OwnerUserId==current.Id||s.TargetUserId==current.Id).Select(s=>new{s.Id,s.OwnerUserId,s.TargetUserId,s.StorageId,s.RelativePath,s.CanWrite,s.CreatedUtc}));return;}
if(p=="/api/shares"&&c.Request.HttpMethod=="POST"){var q=await JsonSerializer.DeserializeAsync<ShareRequest>(c.Request.InputStream,json);if(q==null||!store.State.Users.Any(u=>u.Id==q.TargetUserId)||!store.State.Storage.Any(s=>s.Id==q.StorageId&&CanAccess(s,current))){await Reply(c,400,new{error="Ungültige Freigabe"});return;}var grant=new ShareGrant{OwnerUserId=current.Id,TargetUserId=q.TargetUserId,StorageId=q.StorageId,RelativePath=q.RelativePath??"",CanWrite=q.CanWrite};store.State.Shares.Add(grant);store.Save();await Reply(c,201,grant);return;}await Reply(c,404,new{error="Not found"});}catch(Exception e){await Reply(c,500,new{error=e.Message});}}
 static void CleanupTransfers(StateStore store){var now=DateTime.UtcNow;var changed=false;foreach(var t in store.State.Transfers.ToList()){var expired=t.ExpiresUtc!=null&&t.ExpiresUtc<=now;var auto=t.AutoDeleteDays>0&&t.CreatedUtc.AddDays(t.AutoDeleteDays)<=now;if(!expired&&!auto)continue;if(auto){var s=store.State.Storage.FirstOrDefault(x=>x.Id==t.StorageId);if(s!=null&&s.Role.Equals("Transfer",StringComparison.OrdinalIgnoreCase)){var target=SafePath(s.Path,t.RelativePath);try{if(target!=null&&File.Exists(target))File.Delete(target);else if(target!=null&&Directory.Exists(target))Directory.Delete(target,true);}catch{}}}store.State.Transfers.Remove(t);changed=true;}if(changed)store.Save();} static string TransferPage(TransferLink t,string token,bool badPassword){var locked=!string.IsNullOrEmpty(t.PasswordHash);var pw=locked?$"<form method='post' action='/transfer/{token}/unlock'><input name='password' type='password' placeholder='Passwort' style='padding:12px;border:1px solid #dbe3ea;border-radius:8px'><button type='submit'>Freischalten</button></form>":"";var dl=!locked&&t.AllowDownload?$"<button onclick=\"location.href='/transfer/{token}/download'\">Herunterladen</button>":"";var up=!locked&&t.AllowUpload?$"<input id='f' type='file'><button onclick=\"let f=document.getElementById('f').files[0];if(!f)return;fetch('/transfer/{token}/upload?name='+encodeURIComponent(f.name),{{method:'POST',body:f}}).then(r=>alert(r.ok?'Upload abgeschlossen':'Upload fehlgeschlagen'))\">Hochladen</button>":"";return $"<!doctype html><meta charset='utf-8'><title>i-NET-PROMO Transfer</title><body style='font-family:Segoe UI;background:#f6f8fb;padding:40px'><main style='max-width:720px;margin:auto;background:white;padding:32px;border-radius:14px'><img src='/brand-logo' style='max-width:260px;max-height:100px;object-fit:contain'><b style='color:#00a9c9'>CLOUDSERVICE TRANSFER</b><h2>{System.Net.WebUtility.HtmlEncode(Path.GetFileName(t.RelativePath))}</h2>{(badPassword?"<p style='color:#b00020'>Passwort falsch.</p>":"")}{pw}<div style='display:flex;gap:12px;margin-top:20px'>{dl}{up}</div></main></body>";}  static async Task Html(HttpListenerContext c,int status,string html){var b=Encoding.UTF8.GetBytes(html);c.Response.StatusCode=status;c.Response.ContentType="text/html; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();} static UserAccount? Authenticate(HttpListenerContext c,StateStore store){var h=c.Request.Headers["Authorization"];var t=h!=null&&h.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase)?h[7..].Trim():"";if(string.IsNullOrWhiteSpace(t))return null;if(!sessions.TryGetValue(t,out var s)||s.Expires<=DateTime.UtcNow){sessions.TryRemove(t,out _);return null;}return store.State.Users.FirstOrDefault(x=>x.Id==s.UserId);} static bool CanAccess(StorageAssignment s,UserAccount u)=>u.IsAdmin||s.UserId==u.Id||s.GroupId!=null&&u.GroupIds.Contains(s.GroupId); static ShareGrant? SharedAccess(StateStore store,UserAccount u,string storageId,string relative,bool write){var rel=(relative??"").Replace('\\','/').Trim('/');return store.State.Shares.FirstOrDefault(g=>g.TargetUserId==u.Id&&g.StorageId==storageId&&(!write||g.CanWrite)&&(rel.Equals((g.RelativePath??"").Replace('\\','/').Trim('/'),StringComparison.OrdinalIgnoreCase)||rel.StartsWith((g.RelativePath??"").Replace('\\','/').Trim('/')+"/",StringComparison.OrdinalIgnoreCase)));} static string? SafePath(string root,string relative){var fullRoot=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;var full=Path.GetFullPath(Path.Combine(root,relative??""));return (full+Path.DirectorySeparatorChar).StartsWith(fullRoot,StringComparison.OrdinalIgnoreCase)?full:null;} sealed record FolderRequest(string StorageId,string? Path,string Name); sealed record PathRequest(string StorageId,string Path); sealed record RenameRequest(string StorageId,string Path,string NewName); static async Task Reply(HttpListenerContext c,int status,object o){var b=Encoding.UTF8.GetBytes(JsonSerializer.Serialize(o,json));c.Response.StatusCode=status;c.Response.ContentType="application/json; charset=utf-8";c.Response.ContentLength64=b.Length;await c.Response.OutputStream.WriteAsync(b);c.Response.Close();}
 sealed record TransferRequest(string StorageId,string? RelativePath,string? Password,DateTime? ExpiresUtc,bool AllowDownload,bool AllowUpload,int AutoDeleteDays); sealed record Login(string UserName,string Password); sealed record ShareRequest(string OwnerUserId,string TargetUserId,string StorageId,string? RelativePath,bool CanWrite);
